<script setup lang="ts">
import { onBeforeUnmount, onMounted, nextTick, ref, watch } from 'vue';import { useRoute } from 'vue-router';import TopBar from '@/components/ui/TopBar.vue';import Avatar from '@/components/ui/Avatar.vue';import Icon from '@/components/ui/Icon.vue';import { useChatStore } from '@/stores/chat';import { useSessionStore } from '@/stores/session';import { formatTime } from '@/services/format';
const route=useRoute(),chat=useChatStore(),session=useSessionStore();const eventId=String(route.params.eventId),text=ref(''),box=ref<HTMLElement|null>(null);onMounted(()=>chat.startPolling(eventId));onBeforeUnmount(()=>chat.stopPolling());watch(()=>chat.messages.length,async()=>{await nextTick();if(box.value)box.value.scrollTop=box.value.scrollHeight});
async function send(){const value=text.value.trim();if(!value)return;text.value='';await chat.send(eventId,value)}
async function edit(id:string,current:string){const t=prompt('Изменить сообщение:',current);if(t?.trim()){await chat.edit(id,t.trim());await chat.loadMessages(eventId)}}
async function remove(id:string){if(confirm('Удалить сообщение?')){await chat.remove(id);await chat.loadMessages(eventId)}}
</script>
<template><section class="screen chat-page"><TopBar back title="Чат участников"/><div ref="box" class="messages"><div v-if="!chat.messages.length" class="empty chat-empty">Сообщений пока нет. Напишите первым.</div><div v-for="m in chat.messages" :key="m.id" class="message" :class="{mine:m.sender_id===session.user?.id}"><Avatar v-if="m.sender_id!==session.user?.id" :name="m.sender?.display_name||'Гость'" :src="m.sender?.avatar_url" size="sm"/><div class="bubble"><header><b>{{m.sender?.display_name||'Вы'}}</b><time>{{formatTime(m.created_at)}}</time></header><p>{{m.text}}</p><small v-if="m.edited_at">изменено</small><footer v-if="m.sender_id===session.user?.id"><button @click="edit(m.id,m.text)">изменить</button><button @click="remove(m.id)">удалить</button></footer></div></div></div><form class="chat-composer" @submit.prevent="send"><textarea v-model="text" rows="1" maxlength="2000" placeholder="Написать участникам…" @keydown.enter.exact.prevent="send"></textarea><button><Icon name="send"/></button></form></section></template>
